/*
 * Pure validation boundaries of metadata lookup: the allowlist DSL, complete decoding, the source
 * parsers, and the outbound URL builders and per-hop destination policies.
 */
const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const invalid = (shape: LookupShape, value: unknown, label = JSON.stringify(value) ?? String(value)) =>
    assert.throws(() => validateLookupShape(shape, value), LookupShapeError, label);
const loneHigh = String.fromCharCode(0xd800), loneLow = String.fromCharCode(0xdc00);
const mbid = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
/** A plain copy, because the complete parser and some fixtures build prototype-less objects. */
const plain = <T>(value: T): T => JSON.parse(JSON.stringify(value));

test('a projection keeps only declared keys in declaration order, copies values and is idempotent', () => {
    const shape = object({ b: string(10), a: integer(0, 5, { optional: true }), c: boolean({ nullable: true }), list: array(object({ id: string(4) }), 3) });
    const input = { z: 'dropped', c: null, list: [{ id: 'x1', extra: true }], b: 'kept', a: 3 };
    const output = validateLookupShape<Record<string, unknown>>(shape, input);
    assert.deepEqual(Object.keys(output), ['b', 'a', 'c', 'list']);
    assert.deepEqual(output, { b: 'kept', a: 3, c: null, list: [{ id: 'x1' }] });
    assert.notEqual(output.list, input.list);
    assert.deepEqual(validateLookupShape(shape, output), output);
    assert.deepEqual(Object.keys(validateLookupShape<object>(shape, { b: 'kept', c: true, list: [] })), ['b', 'c', 'list'], 'an absent optional field stays absent');
    assert.deepEqual(validateLookupShape(object({ a: string(2) }), Object.assign(Object.create(null), { a: 'x' })), { a: 'x' }, 'prototype-less parser output is accepted');
});

test('wrong types, bounds, patterns, lone surrogates and non-plain objects reject the whole value', () => {
    invalid(string(3), 'abcd'); invalid(string(3), 3); invalid(string(10, { pattern: /^[A-Z]{2}$/ }), 'us');
    invalid(string(10), `a${loneHigh}`); invalid(string(10), `${loneLow}a`); invalid(string(10), `${loneLow}${loneHigh}`);
    assert.equal(validateLookupShape(string(4), String.fromCodePoint(0x1f3b5)), String.fromCodePoint(0x1f3b5), 'a surrogate pair is ordinary text');
    invalid(integer(0, 10), 11); invalid(integer(0, 10), -1); invalid(integer(0, 10), 1.5); invalid(integer(0, 10), '1');
    invalid(integer(0, Number.MAX_SAFE_INTEGER), 2 ** 53);
    invalid(boolean(), 'true'); invalid(boolean(), 0);
    invalid(array(string(2), 2), ['a', 'b', 'c']); invalid(array(string(2), 2), 'ab'); invalid(array(string(1), 5), ['a', 'bb']);
    for (const value of [[], new Date(0), new (class Box { a = 'x'; })(), 'a', {}, { a: null }]) invalid(object({ a: string(2) }), value, String(value));
    invalid(object({ inner: object({ n: integer(0, 1) }) }), { inner: { n: 2 } });
    invalid(string(1, { optional: true }), null, 'optional is not nullable');
    assert.equal(validateLookupShape(string(1, { nullable: true }), null), null);
    assert.throws(() => validateLookupShape(string(1), undefined), LookupShapeError);
    const id = oneOf(integer(1, 100), string(5, { pattern: /^\d+$/ }));
    assert.equal(validateLookupShape(id, 7), 7); assert.equal(validateLookupShape(id, '123'), '123');
    for (const value of [0, 'abc', true, null, [1]]) invalid(id, value);
});

test('date() accepts empty, year, month and day precision on a real calendar and nothing else', () => {
    for (const value of ['', '1976', '1976-12', '1976-12-08', '2024-02-29', '2000-02-29', '0001-01-01']) assert.equal(validateLookupShape(date(), value), value, value);
    for (const value of ['2023-02-29', '1900-02-29', '1976-13', '1976-00', '1976-12-32', '1976-04-31', '1976-12-00', '0000', '76-12-08', '1976/12/08',
        '1976-1-8', '1976-12-08T00:00:00Z', ' 1976', 1976, null]) invalid(date(), value);
    assert.equal(validateLookupShape(date({ nullable: true }), null), null);
    assert.deepEqual(parseLookupDate('1976-12-08'), { year: 1976, month: 12, day: 8 });
    assert.deepEqual(parseLookupDate('1976-12'), { year: 1976, month: 12, day: null });
    assert.deepEqual(parseLookupDate('1976'), { year: 1976, month: null, day: null });
    assert.equal(parseLookupDate(''), null); assert.equal(parseLookupDate(undefined), null);
});

test('decoding is fatal UTF-8 followed by the complete JSON parser', () => {
    assert.deepEqual(plain(decodeLookupJson(Buffer.from('{"title":"パンドラコール","n":[1,2.5,null,true]}'))), { title: 'パンドラコール', n: [1, 2.5, null, true] });
    const nested = (levels: number) => Buffer.from(`{"a":${'['.repeat(levels)}${']'.repeat(levels)}}`);
    assert.doesNotThrow(() => decodeLookupJson(nested(20)), 'nesting 20 levels below the root is accepted');
    const rawNewline = String.fromCharCode(10);
    for (const bytes of [Buffer.from([0xc3, 0x28]), Buffer.from([0xc0, 0xaf]), Buffer.from([0xed, 0xa0, 0x80]), Buffer.from([0x22, 0xff, 0x22]),
        Buffer.from('{"a":1,"a":2}'), Buffer.from('{"a":{"b":1,"b":1}}'), nested(21), Buffer.from('{"a":1} x'), Buffer.from('{"a":NaN}'),
        Buffer.from(`{"a":"x${rawNewline}y"}`), Buffer.from(''), Buffer.from("{'a':1}"), Buffer.from('[1,]'), Buffer.from('{"a":1e999}')]) {
        assert.throws(() => decodeLookupJson(bytes), LookupShapeError, bytes.toString('hex'));
    }
    // An escaped lone surrogate decodes, and the shape then rejects it.
    const escaped = Buffer.from(['{"t":"', '\\', 'u', 'd800"}'].join(''));
    invalid(object({ t: string(10) }), decodeLookupJson(escaped), 'escaped lone surrogate');
});

/** The smallest release lookup the shape accepts. */
const minimalRelease = (overrides: Record<string, unknown> = {}) => ({
    id: mbid(1), title: 'Synthetic Release',
    media: [{ position: 1, tracks: [{ position: 1, number: '1', title: 'One', recording: { id: mbid(2) } }] }], ...overrides
});
const withTrack = (track: Record<string, unknown>, recording: Record<string, unknown> = {}) => minimalRelease({
    media: [{ position: 1, tracks: [{ position: 1, number: '1', title: 'One', ...track, recording: { id: mbid(2), ...recording } }] }]
});

test('a minimal MusicBrainz release parses with explicit nulls, and track length falls back to the recording', () => {
    assert.deepEqual(parseMusicBrainzRelease(minimalRelease()), {
        releaseId: mbid(1), releaseGroupId: null, title: 'Synthetic Release', status: null, artistCredit: [], labels: [],
        barcode: null, barcodeText: null, country: null, date: null, primaryType: null, secondaryTypes: [], trackCount: 1,
        media: [{ position: 1, format: null, tracks: [{ position: 1, number: '1', title: 'One', lengthMs: null, recordingId: mbid(2), isrcs: [] }] }],
        groupFirstReleaseDate: null, frontArtwork: null
    });
    const lengthOf = (track: Record<string, unknown>, recording: Record<string, unknown> = {}) => parseMusicBrainzRelease(withTrack(track, recording)).media[0].tracks[0].lengthMs;
    assert.equal(lengthOf({ length: 1000 }, { length: 2000 }), 1000);
    assert.equal(lengthOf({ length: null }, { length: 2000 }), 2000);
    assert.equal(lengthOf({}, { length: 2000 }), 2000);
    assert.equal(lengthOf({}, { length: null }), null);
    for (const length of [0, -1, 86_400_001, 1.5, '1000']) assert.throws(() => parseMusicBrainzRelease(withTrack({ length })), LookupShapeError, String(length));
    const credited = parseMusicBrainzRelease(minimalRelease({ 'artist-credit': [{ name: 'Eagles', artist: { id: mbid(3), name: 'Eagles' } }],
        'release-group': { id: mbid(4), 'primary-type': 'Album', 'secondary-types': ['Soundtrack'], 'first-release-date': '1976-12-08' },
        'cover-art-archive': { front: true, count: 3 }, date: '', country: 'XW' }));
    assert.deepEqual(credited.artistCredit, [{ name: 'Eagles', joinPhrase: '', artistId: mbid(3), artistName: 'Eagles' }], 'a missing join phrase is empty');
    assert.deepEqual([credited.releaseGroupId, credited.primaryType, credited.secondaryTypes, credited.groupFirstReleaseDate, credited.date, credited.frontArtwork, credited.country],
        [mbid(4), 'Album', ['Soundtrack'], { year: 1976, month: 12, day: 8 }, null, true, 'XW']);
});

test('MusicBrainz bounds, identifiers and codes reject the whole response, while a malformed barcode is only no barcode', () => {
    const credit = (index: number) => ({ name: `Artist ${index}`, joinphrase: ', ', artist: { id: mbid(100 + index), name: `Artist ${index}` } });
    assert.equal(parseMusicBrainzRelease(minimalRelease({ 'artist-credit': Array.from({ length: 50 }, (_unused, index) => credit(index)) })).artistCredit.length, 50);
    const medium = (position: number) => ({ position, tracks: [] });
    const rejected: [string, Record<string, unknown>][] = [
        ['51 credits', minimalRelease({ 'artist-credit': Array.from({ length: 51 }, (_unused, index) => credit(index)) })],
        ['101 media', minimalRelease({ media: Array.from({ length: 101 }, (_unused, index) => medium(index + 1)) })],
        ['1000 tracks', minimalRelease({ media: [{ position: 1, tracks: Array.from({ length: 1000 }, (_unused, index) => ({ position: index + 1, number: String(index + 1), title: 'T', recording: { id: mbid(2) } })) }] })],
        ['lowercase country', minimalRelease({ country: 'xw' })],
        ['uppercase MBID', minimalRelease({ id: mbid(1).toUpperCase().replace('-4000-', '-4ABC-') })],
        ['nil-shaped bad MBID', minimalRelease({ id: '00000000-0000-0000-0000-00000000000g' })],
        ['65-character barcode', minimalRelease({ barcode: '1'.repeat(65) })],
        ['201-character join phrase', minimalRelease({ 'artist-credit': [{ ...credit(1), joinphrase: 'x'.repeat(201) }] })],
        ['label without name', minimalRelease({ 'label-info': [{ label: { id: mbid(5) } }] })],
        ['media missing', { id: mbid(1), title: 'No media' }],
        ['bad ISRC', withTrack({}, { isrcs: ['usaaa2000001'] })]
    ];
    for (const [label, json] of rejected) assert.throws(() => parseMusicBrainzRelease(json), LookupShapeError, label);
    for (const [barcode, expected] of [['075596050920', '075596050920'], ['0075596050920', '0075596050920'], ['075596050921', null], ['', null], ['0000000000000', null], [null, null]] as const) {
        const parsed = parseMusicBrainzRelease(minimalRelease({ barcode }));
        assert.equal(parsed.barcode, expected, String(barcode)); assert.equal(parsed.barcodeText, barcode, String(barcode));
    }
    const labelled = parseMusicBrainzRelease(minimalRelease({ 'label-info': [{ 'catalog-number': null, label: null }, { 'catalog-number': 'BACD-0001', label: { id: mbid(5), name: '株式会社Yostar' } }] }));
    assert.deepEqual(labelled.labels, [{ name: null, labelId: null, catalogNumber: null }, { name: '株式会社Yostar', labelId: mbid(5), catalogNumber: 'BACD-0001' }]);
});

test('MusicBrainz searches, browse and ISRC answers parse their allowlisted fields and enforce their bounds', () => {
    const summary = (overrides: Record<string, unknown> = {}) => ({ id: mbid(1), title: 'Hotel California', media: [{ format: 'CD', 'track-count': 9 }, { 'track-count': 10 }], ...overrides });
    const search = parseMusicBrainzReleaseSearch({ count: 1, offset: 0, releases: [summary({ score: 100 })], created: '2026-10-18T00:00:00Z' });
    assert.equal(search.count, 1);
    assert.deepEqual([search.releases[0].trackCount, search.releases[0].media, search.releases[0].score], [19, [{ format: 'CD', trackCount: 9 }, { format: null, trackCount: 10 }], 100],
        'without track-count the media totals count');
    assert.equal(parseMusicBrainzReleaseSearch({ count: 1, releases: [summary({ 'track-count': 9 })] }).releases[0].trackCount, 9);
    for (const json of [{ count: 1, releases: [summary({ score: 101 })] }, { count: -1, releases: [] }, { releases: [] }, { count: 0, releases: Array(101).fill(summary()) }]) {
        assert.throws(() => parseMusicBrainzReleaseSearch(json), LookupShapeError, JSON.stringify(json).slice(0, 80));
    }
    assert.equal(parseMusicBrainzBrowse({ 'release-count': 1, releases: [summary()] }).length, 1);
    assert.throws(() => parseMusicBrainzBrowse({ count: 1, releases: [summary()] }), LookupShapeError, 'browse answers carry release-count');

    const recordings = parseMusicBrainzRecordingSearch({ count: 1, recordings: [{ id: mbid(2), title: 'パンドラコール', length: 217030,
        releases: [{ id: mbid(1), title: 'パンドラコール', 'track-count': 1, date: '2022-08-17', country: 'JP',
            'release-group': { id: mbid(4), 'primary-type': 'Single' }, media: [{ position: 1, format: 'Digital Media', 'track-offset': 0 }] }] }] });
    assert.deepEqual(recordings.recordings[0], { recordingId: mbid(2), title: 'パンドラコール', lengthMs: 217030, artistCredit: [],
        releases: [{ releaseId: mbid(1), title: 'パンドラコール', trackCount: 1, media: [{ position: 1, format: 'Digital Media', trackOffset: 0 }],
            date: { year: 2022, month: 8, day: 17 }, country: 'JP', primaryType: 'Single', secondaryTypes: [] }] });
    assert.deepEqual(parseMusicBrainzIsrc({ isrc: 'JPY392200483', recordings: [{ id: mbid(2), title: 'パンドラコール', releases: [{ id: mbid(1) }, { id: mbid(3) }] }] }),
        { isrc: 'JPY392200483', recordings: [{ recordingId: mbid(2), title: 'パンドラコール', lengthMs: null, releaseIds: [mbid(1), mbid(3)] }] });
    for (const json of [{ isrc: 'jpy392200483', recordings: [] }, { isrc: 'JPY392200483', recordings: [{ id: 'x', title: 'T' }] }]) {
        assert.throws(() => parseMusicBrainzIsrc(json), LookupShapeError, JSON.stringify(json));
    }
});

/** iTunes items carrying the store, preview and artist links that must never survive parsing. */
const collection = (overrides: Record<string, unknown> = {}) => ({
    wrapperType: 'collection', collectionType: 'Album', collectionId: 1689358563, artistId: 1, collectionName: 'パンドラコール - Single', artistName: 'ヰ世界情緒',
    trackCount: 1, releaseDate: '2022-08-17T07:00:00Z', country: 'JPN', artworkUrl100: 'https://is1-ssl.mzstatic.com/image/thumb/x/100x100bb.jpg',
    artworkUrl60: 'https://is1-ssl.mzstatic.com/image/thumb/x/60x60bb.jpg', collectionViewUrl: 'https://music.apple.com/jp/album/x', artistViewUrl: 'https://music.apple.com/jp/artist/x',
    ...overrides
});
const song = (overrides: Record<string, unknown> = {}) => ({
    wrapperType: 'track', kind: 'song', trackId: 1689358564, collectionId: 1689358563, trackName: 'パンドラコール', collectionName: 'パンドラコール - Single',
    artistName: 'ヰ世界情緒', discNumber: 1, discCount: 1, trackNumber: 1, trackCount: 1, trackTimeMillis: 217030,
    previewUrl: 'https://audio-ssl.itunes.apple.com/x.m4a', trackViewUrl: 'https://music.apple.com/jp/album/x?i=1', ...overrides
});
const itunes = (results: unknown[], resultCount = results.length) => ({ resultCount, results });

test('iTunes keeps collections and songs only, at day precision, with artwork only on the fixed image hosts', () => {
    const parsed = parseItunesResponse(itunes([collection(), song(), { wrapperType: 'artist', artistName: 'ヰ世界情緒' },
        song({ kind: 'music-video' }), song({ kind: undefined }), { wrapperType: 'audiobook', collectionId: 2 }]));
    assert.deepEqual(parsed, {
        collections: [{ collectionId: '1689358563', collectionName: 'パンドラコール - Single', artistName: 'ヰ世界情緒', trackCount: 1,
            releaseDate: { year: 2022, month: 8, day: 17 }, country: 'JPN', artworkUrl: 'https://is1-ssl.mzstatic.com/image/thumb/x/100x100bb.jpg' }],
        tracks: [{ trackId: '1689358564', collectionId: '1689358563', collectionName: 'パンドラコール - Single', trackName: 'パンドラコール', artistName: 'ヰ世界情緒',
            discNumber: 1, discCount: 1, trackNumber: 1, trackTimeMillis: 217030 }]
    });
    assert.doesNotMatch(JSON.stringify(parsed), /music\.apple\.com|audio-ssl|previewUrl|ViewUrl|60x60/);
    for (const artworkUrl100 of ['https://is6-ssl.mzstatic.com/a.jpg', 'http://is1-ssl.mzstatic.com/a.jpg', 'https://is1-ssl.mzstatic.com.example.test/a.jpg',
        'https://example.test/a.jpg', 'https://is1-ssl.mzstatic.com:8443/a.jpg', 'https://user@is1-ssl.mzstatic.com/a.jpg', 'https://is1-ssl.mzstatic.com/a b.jpg']) {
        assert.equal(parseItunesResponse(itunes([collection({ artworkUrl100 })])).collections[0].artworkUrl, null, artworkUrl100);
    }
    assert.deepEqual(parseItunesResponse(itunes([collection({ releaseDate: '2024-02-29T08:00:00Z' })])).collections[0].releaseDate, { year: 2024, month: 2, day: 29 });
    assert.deepEqual(parseItunesResponse(itunes([])), { collections: [], tracks: [] });
});

test('an iTunes count mismatch, a missing identity field or an out-of-bound value rejects the whole response', () => {
    const rejected: [string, unknown][] = [
        ['count above results', itunes([collection()], 2)], ['count below results', itunes([collection(), song()], 1)],
        ['more than 200 results', itunes(Array(201).fill(song()))], ['collection without name', itunes([collection({ collectionName: undefined })])],
        ['song without track ID', itunes([song({ trackId: undefined })])], ['song without collection ID', itunes([song({ collectionId: undefined })])],
        ['string ID', itunes([collection({ collectionId: '1689358563' })])], ['zero ID', itunes([song({ trackId: 0 })])],
        ['impossible day', itunes([collection({ releaseDate: '2023-02-29T08:00:00Z' })])], ['date without time', itunes([collection({ releaseDate: '2022-08-17' })])],
        ['over-long duration', itunes([song({ trackTimeMillis: 86_400_001 })])], ['lowercase country', itunes([collection({ country: 'jpn' })])],
        ['missing wrapper type', itunes([{ collectionId: 1 }])], ['results not an array', { resultCount: 0, results: {} }]
    ];
    for (const [label, json] of rejected) assert.throws(() => parseItunesResponse(plain(json)), LookupShapeError, label);
});

test('iTunes IDs share one 12-digit bound, so every parsed ID can be looked up again', () => {
    const parsed = parseItunesResponse(itunes([collection({ collectionId: 999_999_999_999 }), song({ collectionId: 999_999_999_999, trackId: 999_999_999_998 })]));
    assert.equal(parsed.collections[0].collectionId, '999999999999');
    assert.equal(itunesUrls.lookupId(parsed.collections[0].collectionId, 'jp').searchParams.get('id'), '999999999999');
    assert.equal(itunesUrls.lookupId(parsed.tracks[0].trackId, 'us').searchParams.get('id'), '999999999998');
    for (const json of [itunes([collection({ collectionId: 1_000_000_000_000 })]), itunes([song({ trackId: 1_000_000_000_000 })])]) {
        assert.throws(() => parseItunesResponse(plain(json)), LookupShapeError, 'a 13-digit ID rejects the whole response');
    }
});

test('a Cover Art Archive listing must name the requested release and yields identities, flags, known types and sizes only', () => {
    const id = '83afdb26-9c27-4ec6-ad70-25b8cb897a31', other = '24ae881f-7cb3-4c43-b80e-70332cd7c50d';
    const image = (overrides: Record<string, unknown> = {}) => ({ id: 32500502536, front: true, back: false, approved: true, edit: 1, comment: '',
        types: ['Front', 'Hologram', 'Booklet'], image: `http://coverartarchive.org/release/${id}/32500502536.jpg`,
        thumbnails: { 250: 'https://example.test/250.jpg', 1200: 'https://example.test/1200.jpg', small: 'https://example.test/s.jpg', large: 'https://example.test/l.jpg' }, ...overrides });
    const listing = (images: unknown[], release = `https://musicbrainz.org/release/${id}`) => ({ images, release });
    const parsed = parseCoverArtListing(listing([image(), image({ id: '9786783001', front: false, back: true, types: [], thumbnails: undefined })]), id.toUpperCase());
    assert.deepEqual(parsed, { releaseId: id, images: [
        { imageId: '32500502536', front: true, back: false, approved: true, types: ['Front', 'Booklet'], sizes: [250, 1200] },
        { imageId: '9786783001', front: false, back: true, approved: true, types: [], sizes: [] }
    ] });
    assert.doesNotMatch(JSON.stringify(parsed), /https?:|example\.test|archive\.org/);
    assert.equal(parseCoverArtListing(listing([], `http://musicbrainz.org/release/${id}`), id).images.length, 0, 'an http release link is accepted');
    for (const [label, json] of [
        ['another release', listing([], `https://musicbrainz.org/release/${other}`)], ['trailing slash', listing([], `https://musicbrainz.org/release/${id}/`)],
        ['another host', listing([], `https://example.test/release/${id}`)], ['zero ID', listing([image({ id: '0' })])], ['fractional ID', listing([image({ id: 1.5 })])],
        ['negative ID', listing([image({ id: -1 })])], ['21-digit ID', listing([image({ id: '1'.repeat(21) })])], ['missing flag', listing([image({ approved: undefined })])],
        ['31 types', listing([image({ types: Array(31).fill('Front') })])], ['201 images', listing(Array(201).fill(image()))], ['missing release', { images: [] }]
    ] as const) assert.throws(() => parseCoverArtListing(plain(json), id), LookupShapeError, label);
});

test('URL builders produce the exact recorded URLs with normalized identifiers', () => {
    assert.equal(musicBrainzUrls.release('24AE881F-7CB3-4C43-B80E-70332CD7C50D').href,
        'https://musicbrainz.org/ws/2/release/24ae881f-7cb3-4c43-b80e-70332cd7c50d?inc=artist-credits+labels+recordings+release-groups+isrcs&fmt=json');
    assert.equal(musicBrainzUrls.releaseSearch({ release: 'Hotel California', artist: 'Eagles' }).href,
        'https://musicbrainz.org/ws/2/release?query=release%3A%22Hotel+California%22+AND+artist%3A%22Eagles%22&fmt=json&limit=25');
    assert.equal(musicBrainzUrls.recordingSearch({ recording: 'Pandora Call' }).href,
        'https://musicbrainz.org/ws/2/recording?query=recording%3A%22Pandora+Call%22&fmt=json&limit=25');
    assert.equal(musicBrainzUrls.releaseGroupBrowse('836f349a-0434-3e8b-a0bc-261f77a9f99c').href,
        'https://musicbrainz.org/ws/2/release?release-group=836f349a-0434-3e8b-a0bc-261f77a9f99c&inc=artist-credits+labels+media&fmt=json&limit=100');
    assert.equal(musicBrainzUrls.isrc('jp-y39-22-00483').href, 'https://musicbrainz.org/ws/2/isrc/JPY392200483?inc=releases&fmt=json');
    assert.equal(itunesUrls.search('  Hotel  California Eagles ', 'us', 'album').href,
        'https://itunes.apple.com/search?term=Hotel+California+Eagles&country=us&media=music&entity=album&limit=25');
    assert.equal(itunesUrls.lookupId(1689358563, 'jp').href, 'https://itunes.apple.com/lookup?id=1689358563&entity=song&country=jp&limit=200');
    assert.equal(itunesUrls.lookupUpc('0 75596-05092 0', 'us').href, 'https://itunes.apple.com/lookup?upc=075596050920&entity=song&country=us&limit=200');
    assert.equal(coverArtListingUrl('83AFDB26-9C27-4EC6-AD70-25B8CB897A31').href, 'https://coverartarchive.org/release/83afdb26-9c27-4ec6-ad70-25b8cb897a31');
    for (const build of [() => musicBrainzUrls.release('../admin'), () => musicBrainzUrls.releaseGroupBrowse(''), () => musicBrainzUrls.isrc('JPY39'),
        () => itunesUrls.lookupId('0', 'jp'), () => itunesUrls.lookupId(1, 'cn'), () => itunesUrls.lookupUpc('123', 'us'), () => coverArtListingUrl('x')]) {
        assert.throws(build, MetadataLookupInputError);
    }
});

test('MusicBrainz and iTunes hops stay on their fixed host and path prefix', () => {
    const accepts = (policy: (url: URL) => URL | null, url: string) => assert.equal(policy(new URL(url))?.href, new URL(url).href, url);
    const refuses = (policy: (url: URL) => URL | null, url: string) => assert.equal(policy(new URL(url)), null, url);
    for (const url of ['https://musicbrainz.org/ws/2/release/x?fmt=json', 'https://musicbrainz.org:443/ws/2/isrc/X']) accepts(musicBrainzDestination, url);
    for (const url of ['https://musicbrainz.org/ws/1/release', 'https://musicbrainz.org/release/x', 'https://musicbrainz.org/ws/2', 'http://musicbrainz.org/ws/2/release',
        'https://beta.musicbrainz.org/ws/2/release', 'https://musicbrainz.org.example.test/ws/2/', 'https://musicbrainz.org:8443/ws/2/', 'https://user:pw@musicbrainz.org/ws/2/',
        'https://musicbrainz.org/ws/2/release#x', 'https://musicbrainz.org/ws/2/../admin']) refuses(musicBrainzDestination, url);
    for (const url of ['https://itunes.apple.com/search?term=x', 'https://itunes.apple.com/lookup?id=1']) accepts(itunesDestination, url);
    for (const url of ['https://itunes.apple.com/search/', 'https://itunes.apple.com/us/album/x', 'https://itunes.apple.com/WebObjects/MZStore.woa', 'http://itunes.apple.com/search',
        'https://music.apple.com/search', 'https://itunes.apple.com.example.test/search', 'https://itunes.apple.com:8443/search']) refuses(itunesDestination, url);
});

test('lookup terms refuse control, format and link-like text and placeholders are recognized by MBID or name', () => {
    const softHyphen = String.fromCharCode(0xad), byteOrderMark = String.fromCharCode(0xfeff), noBreakSpace = String.fromCharCode(0xa0);
    for (const [value, problem] of [[`a${softHyphen}b`, 'invalidText'], [`${byteOrderMark}Eagles`, 'invalidText'], ['a\tb', 'invalidText'], [`a${loneLow}`, 'invalidText'],
        [42, 'invalidText'], ['', 'empty'], [`${noBreakSpace} `, 'empty'], ['HTTPS://example.test', 'url'], ['see file://x', 'url'], ['WWW.example.test', 'url'],
        ['x'.repeat(201), 'tooLong'], ['x'.repeat(4 * 200 + 65), 'tooLong']] as const) {
        assert.equal(lookupTermProblem(value), problem, JSON.stringify(value));
    }
    for (const value of ['Hotel California: Live', `Hotel${noBreakSpace}California`, 'x  '.repeat(100), 'AC/DC', 'ヰ世界情緒']) {
        assert.equal(lookupTermProblem(value), null, value);
    }
    assert.equal(isPlaceholderCredit('Anything', '89AD4AC3-39F7-470E-963A-56509C546377'), true, 'Various Artists by MBID');
    assert.equal(isPlaceholderCredit(null, '157afde4-4bf5-4039-8ad2-5a15acc85176'), true, '[no label] by MBID');
    for (const name of ['VARIOUS ARTISTS', ' va ', 'V.A.', '[Traditional]', '[anonymous]', 'Unknown Artist', `various${noBreakSpace}artists`]) assert.equal(isPlaceholderCredit(name), true, name);
    for (const name of ['Various Artists Tribute', 'Vanessa', 'Eagles', '', null]) assert.equal(isPlaceholderCredit(name, mbid(9)), false, String(name));
});
